fn single_try_engage(self, version, rnd, player, data, target_id, debug) -> Option<SinglePlanBattle>

// ── L242: 타깃이 (적) 타워 사정권 안이라 다이브가 필요한 상황인가
let get = data.cache.game.vtable[+0x1f0];          // fn(&dyn AbstractGame, usize) -> Option<&Entity>
let in_tower = match get(data.cache.game.ptr, target_id) {
    None      => false,                             // 엔티티 조회 실패 → 다이브 아님
    Some(e)   => tower_discipline::engage_requires_dive(player, data, e),
};

// ── L243: battle 만들기 (두 갈래)
let battle: SinglePlanBattle = if in_tower {
    // L244: 타깃을 한 번 더 조회(같은 vtable 슬롯). 없으면 즉시
    let target = match get(data.cache.game.ptr, target_id) { Some(t) => t, None => return None };

    // L245: 다이브 타당성 게이트
    if !single_battle::single_tower_dive_is_viable(
           version, rnd, player, data, &self.team_plan /*+0xf8*/, target, debug) {
        return None;                                // ★일반 교전으로 폴백하지 않는다 — 교전 자체를 접는다
    }

    // L248: 다이브용 배틀 생성
    let mut b = SinglePlanBattle::new_dive(
           version, BattlePlanGoal::TryKill(target_id, 60), data, player);

    // L249~L250: 다이브할 타워를 고른다
    //   대상 = 상대 진영(1 - player.info.team) 의 넥서스 제외 타워들
    //          (Chain<Flatten<array::IntoIter<Option<&Entity>,6>>, Copied<slice::Iter<&Entity>>>)
    //   기준 = ★내 위치가 아니라 **타깃 엔티티** 기준 최근접
    b.dive_tower = towers.min_by_key(|t| {
                        let dx = abs_diff(t.x /*+0x660*/, target.x);
                        let dy = abs_diff(t.y /*+0x668*/, target.y);
                        dx*dx + dy*dy                // game-core/src/utils.rs:6 distance_sq
                   })
                   .and_then(|t| if t.ty(+0x68) == 2 /*EntityType::Tower*/ {
                                     Some(t.ty.Tower.info.ty /*TowerType, +0x128*/)
                                 } else { None });
    //   → 이터레이터가 비었거나 / min 이 None 이거나 / 최근접이 Tower 가 아니면 dive_tower = None(-1)
    b                                               // L251: b 를 battle 로 이동(144B memcpy)
} else {
    // L253: 평범한 교전 배틀
    SinglePlanBattle::new(version, BattlePlanGoal::TryKill(target_id, 60), data, player)
};

// ── L255: 만든 배틀을 한 번 굴려본다(시험 update)
battle.update(version, rnd, player, data,
              &self.positioning_score /*+0x990*/, &mut self.team_plan /*+0xf8*/, debug);

// ── L256: 굴려본 결과가 '싸우자'로 남아 있는지
let committed = !matches!(battle.sub_goal /*+0x58*/,
                          KitingBack /*3*/ | RunAway /*4*/ | End /*7*/);
//   즉 Trace(0) · Protect(1) · Kiting(2) · Assassin(5) · AssassinReady(6) 면 커밋

// ── L257~L258
if !committed { drop(battle.chats /*+0x68*/); return None; }
Some(battle)
